"""Agent06 확인한 서지·공식 문서 기록 생성. 모델/분석을 실행하지 않음."""
import csv, json, re
from pathlib import Path
BASE=Path(__file__).parent
MISSION=BASE.parents[1]/'RESEARCH_MISSION.md'
text=MISSION.read_text()
section=text.split('## 5.2. 논문 1편당 필수 데이터 필드')[1].split('\n\n')[1]
fields=re.findall(r'`([^`]+)`',section)+['source','needs_followup']
assert len(fields)==32
rows=[]
def add(id,key,title,year,arxiv,venue,axes,rq,data,method,objective,finding,contribution,limitation,transfer,novelty,authors=None,bibkey=None):
    source=BASE/'evidence'/f'{key}_README.md'
    body=source.read_text()
    if authors is None:
        search=body[body.index('@'+bibkey):] if bibkey else body
        m=re.search(r'author\s*=\s*\{(.*?)\},\s*\n',search,re.S)
        authors=' '.join(m.group(1).split()) if m else '미확인'
    url={'finO':'https://raw.githubusercontent.com/facebookresearch/dinov3/FINO/README.md'}.get(key)
    logs=json.loads((BASE/'evidence/sources.json').read_text())
    if url is None: url=next(r['url'] for r in logs if r['key']==key and r.get('http_status')==200)
    row=dict.fromkeys(fields,'해당 없음')
    row.update(paper_id=id,title=title,authors=authors,year=year,venue=venue,doi_or_arxiv='arXiv:'+arxiv,official_url='https://arxiv.org/abs/'+arxiv,version='공식 저장소 2026-11-12 스냅샷; 논문 버전 번호 미확인'+('; README 링크는 v1' if key=='irm' else ''),source_verified='제목·저자·연도·arXiv 식별자를 공식 저장소 BibTeX에서 확인; arXiv 페이지 독립 확인 아님',full_text_access='아니요: 논문 본문 미확인; 공식 README 확인'+('; 구현 코드 일부 확인' if key in ['irm','dinov3'] else ''),discussion_access='아니요: 저자 Discussion 및 미래 제안 미확인',domain='비정서 AI / 표상학습',axis_tags=axes,original_rq=rq,dataset=data,stimulus='원래 AI 연구의 이미지/비디오/상호작용 관측; 개별 항목은 dataset 참조',brain_measurement='없음: 정서·뇌 연구가 아님',model_method=method,training_objective=objective,main_findings='공식 문서 주장(독립 재현 아님): '+finding,scientific_contribution=contribution,limitations='Agent 평가(E3): '+limitation,future_directions='저자 제안은 미확인. Agent 전이 가설(E3): '+transfer,future_direction_source_location='논문 Discussion 접근 없음; 전이 가설은 Agent06 독자 추론',transfer_idea='E3: '+transfer,relevant_datasets='초기 독립 탐색: 특정 뇌 데이터셋의 라벨/시간 정보 가용성 미확인; report.md의 조건부 매핑 참조',novelty_risk=novelty,evidence_level='E1-공식 README/코드 한정; 논문 본문 E0; 전이 주장 E3',agent='06_frontier_ai',verification_date='2026-11-12',source=url+' | 로컬 evidence/'+source.name,needs_followup='논문 본문·Discussion·최종 출판 상태·가까운 정서/신경 선행연구 확인; 체크포인트 다운로드/실행은 미수행')
    rows.append(row)
